package com.example.crm.customer;
import org.springframework.stereotype.Service; import java.util.*;
@Service public class CustomerService { private final CustomerRepository repo; private final CustomerMapper mapper; public CustomerService(CustomerRepository r,CustomerMapper m){repo=r;mapper=m;} public List<CustomerDto> findAll(){return repo.findAll().stream().map(mapper::toDto).toList();} public CustomerDto find(UUID id){return repo.findById(id).map(mapper::toDto).orElseThrow(()->new NoSuchElementException("Customer not found"));} public CustomerDto create(String n,String e,String p){return mapper.toDto(repo.save(mapper.toEntity(n,e,p)));} public CustomerDto update(UUID id,String n,String e,String p){var c=repo.findById(id).orElseThrow(()->new NoSuchElementException("Customer not found"));mapper.update(c,n,e,p);return mapper.toDto(repo.save(c));} public void delete(UUID id){if(!repo.existsById(id))throw new NoSuchElementException("Customer not found");repo.deleteById(id);} }
